∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) {S : Scheduling.Assignment} {s B : ℕ}
  (hf : I.PhaseFails S s B),
  s ≤ I.failureTime hf ∧ ∃ v, I.failureTime hf = I.release (I.owner v) + 88 * B ^ 2 ∧ I.failureTime hf ≤ S v

∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) [inst : DecidableRel I.edge] {S : Scheduling.Assignment}
  {s B : ℕ} (hf : I.PhaseFails S s B),
  Scheduling.deadlineVisible B (I.failureTime hf) (I.readyObservation S (I.failureTime hf)) = true

∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) {otherJobs : ℕ}
  (J : Scheduling.Instance otherJobs vertices) (m : ℕ) (ready : Finset (Fin vertices)),
  (∀ v ∈ ready, I.release (I.owner v) = J.release (J.owner v)) → I.fifoSelect m ready = J.fifoSelect m ready

∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) {m : ℕ} {ready : Finset (Fin vertices)}
  {u v : Fin vertices},
  u ∈ I.fifoSelect m ready → v ∈ ready → v ∉ I.fifoSelect m ready → I.release (I.owner u) ≤ I.release (I.owner v)

∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) {S : Scheduling.Assignment} {s : ℕ}
  (T : Scheduling.Assignment) (u : ℕ),
  {v | I.splice S s T v = s + u} = Finset.image (I.residualVertex (I.survivors S s)) {v | T v = u}

∀ {jobs vertices : ℕ} (I : Scheduling.Instance jobs vertices) {S : Scheduling.Assignment} {s : ℕ}
  (T : Scheduling.Assignment) (v : Fin (I.survivors S s).card),
  I.splice S s T (I.residualVertex (I.survivors S s) v) = s + T v

∀ {jobs work : ℕ} {rule : Scheduling.LayerSizeRule jobs work} {j : Fin jobs} {a w : ℕ}
  {r : Scheduling.LayerRecord jobs work} {rs : List (Scheduling.LayerRecord jobs work)},
  Scheduling.JobLayers rule j a w (r :: rs) → r.start = a ∧ r.stop = a + w

∀ {jobs work : ℕ} {rule : Scheduling.LayerSizeRule jobs work} {j : Fin jobs} {a w : ℕ}
  {r : Scheduling.LayerRecord jobs work} {rs : List (Scheduling.LayerRecord jobs work)},
  Scheduling.JobLayers rule j a w (r :: rs) → r.stop - r.start = w

∀ {jobs work : ℕ} {rule : Scheduling.LayerSizeRule jobs work} {j : Fin jobs} {a w : ℕ}
  {rs : List (Scheduling.LayerRecord jobs work)},
  Scheduling.JobLayers rule j a w rs → ∀ r ∈ rs, r.owner = j ∧ a ≤ r.start ∧ r.start < r.stop ∧ r.stop ≤ work

∀ {jobs work : ℕ} {rule : Scheduling.LayerSizeRule jobs work} {j : Fin jobs} {a w : ℕ}
  {r : Scheduling.LayerRecord jobs work} {rs : List (Scheduling.LayerRecord jobs work)},
  Scheduling.JobLayers rule j a w (r :: rs) → Scheduling.JobLayers rule j r.stop (rule.size j r.stop (r.time + 1)) rs

∀ {jobs work : ℕ} {rule : Scheduling.LayerSizeRule jobs work} {j : Fin jobs} {a w : ℕ}
  {rs : List (Scheduling.LayerRecord jobs work)},
  Scheduling.JobLayers rule j a w rs → (List.map (fun r => r.stop - r.start) rs).sum = work - a

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work},
  Scheduling.LayeredPrefix.CompletionRun hw A rule P Q → ∀ (j : Fin jobs), Q.closed j = work

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayeredPrefix.HistoryLayerRule jobs work}
  {history records : List (Scheduling.LayerRecord jobs work)} {P Q : Scheduling.LayeredPrefix jobs work},
  Scheduling.LayeredPrefix.HistoryRun hw A L rule history P Q records →
    Scheduling.LayeredPrefix.FlexibleRun hw A L P Q records

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records → Scheduling.LayeredPrefix.CompletionRun hw A rule P Q

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs) (k : Fin work), P.closed j ≤ ↑k → ∃ r ∈ records, r.owner = j ∧ r.start ≤ ↑k ∧ ↑k < r.stop

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs),
      Scheduling.JobLayers rule j (P.closed j) (P.width j) (List.filter (fun r => decide (r.owner = j)) records)

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs), List.Pairwise (fun r s => r.time < s.time) (List.filter (fun r => decide (r.owner = j)) records)

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs),
      (Scheduling.recordedKeys records j).card = (List.filter (fun r => decide (r.owner = j)) records).length

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs), ∀ k ∈ Scheduling.recordedKeys records j, P.closed j ≤ ↑k

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records → records.Nodup

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    List.Pairwise (fun a b => a.owner = b.owner → a.stop ≤ b.start) records

∀ {jobs work m L : ℕ} {hm : 0 < m} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule (Scheduling.LayeredPrefix.initial m hm) Q records →
    ∀ (j : Fin jobs) (v u : Fin work), Q.parent j v = some u → u ∈ Scheduling.recordedKeys records j

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ (j : Fin jobs) (v u : Fin work),
      Q.parent j v = some u → P.parent j v = some u ∨ ∃ r ∈ records, r.owner = j ∧ r.key = u

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ {r s : Scheduling.LayerRecord jobs work}, r ∈ records → s ∈ records → r.owner = s.owner → r.time = s.time → r = s

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records → ∀ r ∈ records, P.closed r.owner ≤ r.start

∀ {jobs work m L : ℕ} {hw : 0 < work} {A : Scheduling.DeterministicScheduler m}
  {rule : Scheduling.LayerSizeRule jobs work} {P Q : Scheduling.LayeredPrefix jobs work}
  {records : List (Scheduling.LayerRecord jobs work)},
  Scheduling.LayeredPrefix.RecordedRun hw A rule P Q records →
    ∀ r ∈ records, r.start = P.closed r.owner → r.stop - r.start = P.width r.owner

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → ∀ (b : Fin batches), R.boundary (R.admission b) ≤ B.eligible b + 4 * L

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (b : Fin batches),
  B.eligible b ≤ R.boundary (R.admission b)

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {K a D : ℕ},
  a ≤ K → (∀ k < K, R.boundary (k + 1) - R.boundary k ≤ D) → R.boundary K ≤ R.boundary a + (K - a) * D

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (k : ℕ),
  m * (R.boundary (k + 1) - R.boundary k) ≤ (R.smallFront k).card + m

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {u K t : ℕ},
  u ≤ K → R.boundary u ≤ t → t < R.boundary K → ∃ r, u ≤ r ∧ r < K ∧ R.boundary r ≤ t ∧ t < R.boundary (r + 1)

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → I.FlowBound S (44 * L ^ 2)

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {A K : ℕ},
  A ≤ K → ∑ k ∈ Finset.Ico A K, (R.boundary (k + 1) - R.boundary k) = R.boundary K - R.boundary A

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → I.maxFlow S ≤ 44 * L ^ 2

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {A K : ℕ},
  A ≤ K → ∑ k ∈ Finset.Ico A K, (R.oldService (R.boundary A) k).card ≤ (B.admittedRemaining S (R.boundary A)).card

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → ∀ (k : ℕ), R.boundary (k + 1) - R.boundary k ≤ max 1 (B.small m S (R.boundary k)).card

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (a k : ℕ),
  (R.smallFront k).card ≤ (R.oldService a k).card + (R.youngFront a k).card

∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {k : ℕ} {b : Fin batches},
  b ∈ R.switches k → ∃ v, B.vertexBatch v = b ∧ R.boundary k ≤ S v ∧ S v < R.boundary (k + 1)

∀ {jobs m : ℕ} (A : Scheduling.DeterministicScheduler m) (hm : 0 < m) (long : Fin jobs → Bool) (j : Fin jobs)
  (b : Bool),
  have I := Scheduling.StarChain.toInstance long hm;
  have J := Scheduling.StarChain.toInstance (Function.update long j b) hm;
  ∀ t ≤ A.schedule I (Scheduling.StarChain.root hm j),
    ∀ (v : Fin (jobs * (3 * m))), A.schedule I v = t ↔ A.schedule J v = t
